package run.ikaros.identity; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Pattern; import jakarta.validation.constraints.Size; public record RegisterRequest(@NotBlank @Size(max=64) @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9_.-]*") String username,@NotBlank @Size(min=8,max=128) String password,@NotBlank @Size(max=128) String displayName,@Size(max=320) String email) {}
